parameters.jsonBody:
={{ ({
  "customerNumber": $json.customerNumber,
  "orderDate": ($('Get Deal').first().json.properties.order_date || "").slice(0, 10) || undefined,
  "postingDate": ($('Get Deal').first().json.properties.posting_date || "").slice(0, 10) || undefined,
  "requestedDeliveryDate": ($('Get Deal').first().json.properties.requested_delivery_date || "").slice(0, 10) || undefined,
  "salesOrderLines": $('Get Line Items').first().json.results.map((li) => ({
    "lineType": "Item",
    "lineObjectNumber": String(li.properties.hs_sku).trim(),
    "quantity": Number(li.properties.quantity),
    "unitPrice": Number(li.properties.price)
  }))
}) }}

={{ ({
  "Document_Date": ($('Get Deal').first().json.properties.document_date || "").slice(0, 10) || undefined,
  "Due_Date": ($('Get Deal').first().json.properties.due_date || "").slice(0, 10) || undefined,
  "ERC_Print_Option": $('Get Deal').first().json.properties.print_option || undefined,
  "ERC_FOB_Option": $('Get Deal').first().json.properties.fob_option || undefined,
  "Product_Category": $('Get Deal').first().json.properties.product_category || undefined,
  "WorkDescription": $('Get Deal').first().json.properties.description || undefined,
  "Job_Description": ($('Get Deal').first().json.properties.job_description || "").slice(0, 100) || undefined
}) }}

={{ ({
  "type": "Person",
  "companyNumber": $('Prepare Primary Contact').first().json.companyContactNumber,
  "displayName": $('Prepare Primary Contact').first().json.personName,
  "email": $('Get Contact').first().json.properties.email || undefined,
  "phoneNumber": $('Get Contact').first().json.properties.phone || undefined,
  "mobilePhoneNumber": $('Get Contact').first().json.properties.mobilephone || undefined
}) }}
